mapper.select:
SELECT 
FROM sys_blog
WHERE 
  AND author_id = #{authorId}

  AND status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE sys_blog SET view_count = view_count + 1
WHERE id = #{id}
  AND

UPDATE sys_blog SET like_count = GREATEST(0, COALESCE(like_count, 0) + #{delta})
WHERE id = #{id}
  AND

UPDATE sys_blog SET comment_count = GREATEST(0, COALESCE(comment_count, 0) + #{delta})
WHERE id = #{id}
  AND
